setSidebarOpen:
function setSidebarOpen(open, returnFocus=false){
  $('#sidebar').classList.toggle('open',open);
  $('#sidebarShade').classList.toggle('open',open);
  $('#mobileMenu').setAttribute('aria-expanded',String(open));
  $('.main').inert=open && innerWidth<821;
  if(open && innerWidth<821)$('#sidebarClose').focus();
  if(returnFocus)$('#mobileMenu').focus();
}
